import json
import logging
from typing import Any

from fastapi import WebSocket


logger = logging.getLogger(__name__)


class ConnectionManager:
    """In-memory registry of WebSocket clients keyed by phone number."""

    def __init__(self) -> None:
        self.clients: dict[str, WebSocket] = {}
        # to_phone -> list of pending offer payloads while target is offline
        self.pending_calls: dict[str, list[dict[str, Any]]] = {}
        # call_id -> list of ICE candidate messages while callee not yet connected
        self.pending_candidates: dict[str, list[dict[str, Any]]] = {}

    def register(self, client_id: str, ws: WebSocket) -> None:
        self.clients[client_id] = ws
        logger.info(f"Client {client_id} registered")

    def unregister(self, client_id: str) -> None:
        if client_id in self.clients:
            del self.clients[client_id]
            logger.info(f"Client {client_id} removed")

    def get(self, client_id: str) -> WebSocket | None:
        return self.clients.get(client_id)

    def is_connected(self, client_id: str) -> bool:
        return client_id in self.clients

    async def send_json(self, client_id: str, payload: dict[str, Any]) -> bool:
        ws = self.clients.get(client_id)
        if not ws:
            return False
        try:
            await ws.send_text(json.dumps(payload))
            return True
        except Exception as e:
            logger.error(f"Error sending to {client_id}: {e}")
            return False

    async def notify_availability_change(
        self,
        user_id: str,
        is_available: bool,
        message: str | None = None,
    ) -> bool:
        return await self.send_json(
            user_id,
            {
                "type": "self_availability_update",
                "is_available": is_available,
                "message": message,
            },
        )

    def queue_offer(self, to_id: str, call_info: dict[str, Any]) -> None:
        self.pending_calls.setdefault(to_id, []).append(call_info)
        self.pending_candidates.setdefault(call_info["call_id"], [])

    def queue_candidate(self, call_id: str, candidate_msg: dict[str, Any]) -> None:
        if call_id in self.pending_candidates:
            self.pending_candidates[call_id].append(candidate_msg)

    def take_pending_for(self, client_id: str) -> dict[str, Any] | None:
        """Pop the next pending offer for this client, with its ICE candidates."""
        pending = self.pending_calls.get(client_id)
        if not pending:
            return None

        call_info = pending.pop(0)
        if not pending:
            self.pending_calls.pop(client_id, None)

        call_id = call_info["call_id"]
        candidates = self.pending_candidates.pop(call_id, [])

        return {"call_info": call_info, "candidates": candidates}

    def expire_call(self, to_id: str, call_id: str) -> None:
        if to_id in self.pending_calls:
            self.pending_calls[to_id] = [
                c for c in self.pending_calls[to_id] if c["call_id"] != call_id
            ]
            if not self.pending_calls[to_id]:
                del self.pending_calls[to_id]
        self.pending_candidates.pop(call_id, None)


