async function applyVideoEffects(stream: MediaStream) {
  const { selectedMask, maskEnabled } = useMaskStore.getState()
  const videoTrack = stream.getVideoTracks()[0]
  if (videoTrack) {
    if (maskEnabled && selectedMask !== 'none') {
      // @ts-ignore - _setVideoEffects is private but available in this version of RNWebRTC
      if (typeof videoTrack._setVideoEffects === 'function') {
        // @ts-ignore
        videoTrack._setVideoEffects(['faceMask'])
        setNativeMask(selectedMask)
      }
    } else {
      // @ts-ignore
