    const { state, currentCallId } = get()

    console.log('Call rejected by callee, notification received:', call_id)

    // Check if this rejection is for your current outgoing call
    if (currentCallId === call_id && state === 'calling') {
      console.log('Stopping outgoing call due to callee rejection')

      // Stop ringback sound
      InCallManager.stopRingback()

      // Set state to rejected
      set({ state: 'rejected' })

      // End the call using platform-agnostic interface
      callPlatform.endCall(call_id, 5) // 5 = Call declined by callee

      // Clean up the call
      closeConnection()

      // Navigate back after a brief delay to show rejection state
      setTimeout(() => {
