import { create } from 'zustand'
import { navigateTo } from '@/lib/navigation'
import { useAuthStore } from '@/store/auth'
import { generateUUID } from '@/utils'

type CallState = 'idle' | 'calling' | 'incoming' | 'in-call'

interface CallStore {
  wsInitTriggered: boolean
  currentCallId: string | null

  targetId: string | null // targetId is basically same as peerPhone
  state: CallState
  localStream: MediaStream | null
  remoteStream: MediaStream | null
  ws: WebSocket | null
  pc: RTCPeerConnection | null
  muted: boolean

  init: () => void
  callUser: (targetId: string) => void
  acceptCall: () => void
  rejectCall: () => void
  endCall: () => void
  toggleMute: (mute: boolean) => void
}

export const useCallsStore = create<CallStore>((set, get) => {
  let incomingOffer: RTCSessionDescriptionInit | null = null
  let reconnectAttempts = 0

  const iceServers = { iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] }

  function setupWebSocket() {
    console.log('setupWebSocket')
    const backendUrl = import.meta.env.VITE_BACKEND_URL || 'http://localhost:3001'
    const wsUrl = backendUrl.replace(/^http/, 'ws')
    const ws = new WebSocket(wsUrl)

    ws.onopen = () => {
      reconnectAttempts = 0
      console.log('onOpen')

      const token = useAuthStore.getState().token
      console.log('token')
      console.log(token)
      if (!token) {
        console.error('Missing auth token')
        ws.close()
        return
      }

      ws.send(JSON.stringify({ type: 'register', token }))
    }

    ws.onmessage = async ({ data }) => {
      let msg
      try {
        msg = JSON.parse(data)
      } catch {
        return
      }
      console.log('ws msg')
      console.log(msg)

      const { state, pc } = get()

      switch (msg.type) {
        case 'offer':
          const currentState = get() // Get fresh state
          if (currentState.state === 'idle') {
            incomingOffer = msg.offer

            set({
              targetId: msg.from,
              state: 'incoming',
              currentCallId: msg.callId,
            })

            navigateTo(
              `/calling?peerPhone=${encodeURIComponent(msg.from)}&hasOffer=true`
            )
          }
          break

        case 'answer':
          const { pc } = get() // Get fresh pc
          if (pc) {
            await pc.setRemoteDescription(new RTCSessionDescription(msg.answer))
            set({ state: 'in-call' })
          }
          break

        case 'candidate':
          const currentPc = get().pc // Get fresh pc
          if (currentPc && msg.candidate) {
            try {
              await currentPc.addIceCandidate(
                new RTCIceCandidate(msg.candidate)
              )
            } catch {}
          }
          break

        case 'end':
          closeConnection()

          // Navigate back to the contacts screen
          navigateTo(`/contacts`)
          break

        case 'mic-status':
          // optional: update remote mic status in UI
          break

        case 'self_availability_update':
          useAuthStore.setState((state) => ({
            user: state.user
              ? {
                  ...state.user,
                  is_available: msg.is_available,
                }
              : null,
          }))

          break
      }
    }

    ws.onclose = () => {
      // set({ wsInitTriggered: false })
      tryReconnect()
    }
    ws.onerror = () => {
      // set({ wsInitTriggered: false })
      ws.close()
    }

    set({ ws })
  }

  function tryReconnect() {
    if (reconnectAttempts > 5) return
    reconnectAttempts++
    setTimeout(() => setupWebSocket(), 1000 * reconnectAttempts)
  }

  async function setupPeerConnection() {
    const pc = new RTCPeerConnection(iceServers)
    const ws = get().ws
    const targetId = get().targetId!
    const localStream = await navigator.mediaDevices.getUserMedia({
      audio: true,
      video: true,
    })

    localStream.getTracks().forEach((track) => pc.addTrack(track, localStream))

    pc.onicecandidate = (e) => {
      if (e.candidate && ws?.readyState === 1) {
        ws.send(
          JSON.stringify({
            type: 'candidate',
            to: targetId,
            callId: get().currentCallId,
            candidate: e.candidate,
          })
        )
      }
    }

    pc.ontrack = (e) => {
      set({ remoteStream: e.streams[0] })
    }

    pc.onconnectionstatechange = () => {
      if (['disconnected', 'failed'].includes(pc.connectionState)) {
        closeConnection()
      }
    }

    set({ pc, localStream })
    return pc
  }

  async function callUser(targetId: string, callId: string) {
    // IN_FUTURE: maybe better generate on server to avoid duplicates?
    set({ targetId, state: 'calling', currentCallId: callId })

    const pc = await setupPeerConnection()
    const offer = await pc.createOffer()
    await pc.setLocalDescription(offer)

    get().ws?.send(
      JSON.stringify({ type: 'offer', to: targetId, callId, offer })
    )
  }

  async function acceptCall() {
    const pc = await setupPeerConnection()
    await pc.setRemoteDescription(new RTCSessionDescription(incomingOffer!))
    const answer = await pc.createAnswer()
    await pc.setLocalDescription(answer)

    // const callId = incomingOffer?.callId
    // set({ currentCallId: callId })

    console.log('get().targetId')
    console.log(get().targetId)
    console.log(get().targetId)

    get().ws?.send(
      JSON.stringify({
        type: 'answer',
        to: get().targetId,
        answer,
        callId: get().currentCallId,
      })
    )
    set({ state: 'in-call' })
  }

  function rejectCall() {
    get().ws?.send(JSON.stringify({ type: 'end', to: get().targetId }))
    set({ targetId: null, state: 'idle' })
  }

  function endCall() {
    get().ws?.send(JSON.stringify({ type: 'end', to: get().targetId }))
    closeConnection()
  }

  function closeConnection() {
    get().pc?.close()
    get()
      .localStream?.getTracks()
      .forEach((t) => t.stop())
    set({
      pc: null,
      localStream: null,
      remoteStream: null,
      state: 'idle',
      targetId: null,
      muted: false,
    })
  }

  function toggleMute(mute: boolean) {
    get()
      .localStream?.getAudioTracks()
      .forEach((t) => (t.enabled = !mute))
    set({ muted: mute })

    get().ws?.send(
      JSON.stringify({
        type: 'mic-status',
        to: get().targetId,
        muted: mute,
      })
    )
  }

  return {
    // Add to the return object:
    currentCallId: null,
    targetId: null,
    wsInitTriggered: false,
    state: 'idle',
    localStream: null,
    remoteStream: null,
    ws: null,
    pc: null,
    muted: false,

    init: () => {
      set({ wsInitTriggered: true })
      setupWebSocket()
    },

    callUser,
    acceptCall,
    rejectCall,
    endCall,
    toggleMute,
  }
})

