// callPlatform.ts - Common interface for platform-specific call handling
import { Platform } from 'react-native'
import * as iOSCallHandler from './ios'
import * as androidCallHandler from './android'

import InCallManager from 'react-native-incall-manager'

export interface IncomingCallData {
  call_id: string
  caller_id: string
  caller_phone: string
  isVideoCall?: boolean
}

export interface CallPlatformInterface {
  setupCallSystem: () => Promise<void>
  displayIncomingCall: (callData: IncomingCallData) => void
  answerIncomingCall: (callId: string) => void
  rejectIncomingCall: (callId: string, targetId?: string) => void
  endCall: (callId: string, reason?: number) => void
  dismissCallNotification: () => void
  registerEventListeners: () => void
  cleanupEventListeners: () => void
  setMuted: (callId: string, muted: boolean) => void
}

// Main platform-agnostic interface
class CallPlatform implements CallPlatformInterface {
  private platform: CallPlatformInterface

  constructor() {
    this.platform = Platform.OS === 'ios' ? iOSCallHandler : androidCallHandler
  }

  async setupCallSystem() {
    return this.platform.setupCallSystem()
  }

  displayIncomingCall(callData: IncomingCallData) {
    if (Platform.OS === 'android') {
      InCallManager.startRingtone('_BUNDLE_')
    }
    this.platform.displayIncomingCall(callData)
  }

  answerIncomingCall(callId: string) {
    if (Platform.OS === 'android') {
      InCallManager.stopRingtone()
    }
    InCallManager.start()
    this.platform.answerIncomingCall(callId)
  }

  rejectIncomingCall(callId: string, targetId?: string) {
    if (Platform.OS === 'android') {
      InCallManager.stopRingtone()
    }
    InCallManager.stop()
    this.platform.rejectIncomingCall(callId, targetId)
  }

  endCall(callId: string, reason?: number) {
    this.platform.endCall(callId, reason)
  }

  dismissCallNotification() {
    this.platform.dismissCallNotification()
  }

  registerEventListeners() {
    this.platform.registerEventListeners()
  }

  cleanupEventListeners() {
    this.platform.cleanupEventListeners()
  }

  setMuted(callId: string, muted: boolean) {
    this.platform.setMuted(callId, muted)
  }
}

// Export singleton instance
export const callPlatform = new CallPlatform()

