import { post, get } from '@/api/client'
import { useAuthStore } from '@/store/auth'

export const apiInitiateCall = async (
  calleePhone: string,
  callId: string
): Promise<CallData | null> => {
  try {
    const userAuthToken = useAuthStore.getState().token
    if (!userAuthToken) {
      console.error('No auth token available')
      return null
    }

    const response = await post(
      '/api/calls/initiate',
      { callee_phone: calleePhone, call_uuid: callId },
      {
        Authorization: `Bearer ${userAuthToken}`,
      }
    )
    console.log(response)
    return

    if (response.ok) {
      const data: CallData = await response.json()

      if (!data.notification_sent) {
        console.warn('Push notification may not have been sent to callee')
      }

      return data
    } else {
      const errorData = await response.json()
      const errorMessage =
        errorData.detail || `Failed to initiate call: ${response.statusText}`
      console.error('Failed to initiate call:', errorMessage)

      // Throw error with status for better error handling
      const error = new Error(errorMessage) as Error & { status: number }
      error.status = response.status
      throw error
    }
  } catch (error) {
    console.error('Error initiating call:', error)
    throw error
  }
}

import { post } from '@/api/client'
import { useAuthStore } from '@/store/auth'

export interface CallData {
  success: boolean
  call_id: string
  call_uuid: string
  status?: string
  duplicate?: boolean
  ws_sent?: boolean
  notification_sent?: boolean
  notification_type?: string | string[] | null
}

const authHeaders = () => {
  const userAuthToken = useAuthStore.getState().token
  if (!userAuthToken) {
    console.error('No auth token available')
    return null
  }
  return {
    Authorization: `Bearer ${userAuthToken}`,
  }
}

export const apiInitiateCall = async (
  calleePhone: string,
  callId: string
): Promise<CallData | null> => {
  const headers = authHeaders()
  if (!headers) return null

  return post(
    '/api/calls/initiate',
    { callee_phone: calleePhone, call_uuid: callId },
    headers
  ) as Promise<CallData>
}

export const apiAcceptCall = async (
  callerPhone: string,
  callId?: string | null
): Promise<boolean> => {
  const headers = authHeaders()
  if (!headers) return false

  await post(
    '/api/calls/accept',
    { caller_phone: callerPhone, call_uuid: callId },
    headers
  )
  return true
}

export const apiRejectCall = async (
  callerPhone: string,
  callId?: string | null
): Promise<boolean> => {
  const headers = authHeaders()
  if (!headers) return false

  await post(
    '/api/calls/reject',
    { caller_phone: callerPhone, call_uuid: callId },
    headers
  )
  return true
}

export const apiCancelCall = async (
  calleePhone: string,
  callId?: string | null
): Promise<boolean> => {
  const headers = authHeaders()
  if (!headers) return false

  await post(
    '/api/calls/cancel',
    { callee_phone: calleePhone, call_uuid: callId },
    headers
  )
  return true
}

export const apiEndCall = async (
  peerPhone: string,
  endingRole: 'caller' | 'callee',
  callId?: string | null
): Promise<boolean> => {
  const headers = authHeaders()
  if (!headers) return false

  await post(
    '/api/calls/end',
    {
      caller_phone: endingRole === 'callee' ? peerPhone : undefined,
      callee_phone: endingRole === 'caller' ? peerPhone : undefined,
      call_uuid: callId,
    },
    headers
  )
  return true
}

