  // Predefined schedule rules
  const defaultScheduleRules = [
    { id: 1, day: 'weekdays', time: '09:00:00' },
    { id: 2, day: 'weekdays', time: '13:00:00' },
    { id: 3, day: 'weekdays', time: '17:00:00' },
    { id: 4, day: 'saturday', time: '10:00:00' },
    { id: 5, day: 'sunday', time: '14:00:00' },
  ]

  // Load schedule rules from localStorage on component mount
  useEffect(() => {
    const savedRules = localStorage.getItem('scheduleRules')
    if (savedRules) {
      setScheduleRules(JSON.parse(savedRules))
    } else {
      // If no saved rules, use default rules
      setScheduleRules(defaultScheduleRules)
    }
  }, [])

  // Save schedule rules to localStorage whenever rules change
  useEffect(() => {
    if (scheduleRules.length > 0) {
      localStorage.setItem('scheduleRules', JSON.stringify(scheduleRules))
    }
  }, [scheduleRules])

  const dayOptions = [
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
    'sunday',
    'weekdays',
    'weekends',
    'everyday',
  ]

  const addScheduleRule = () => {
    const id = Math.max(...scheduleRules.map((r) => r.id), 0) + 1
    setScheduleRules([...scheduleRules, { id, ...newRule }])
    setNewRule({ day: 'monday', time: '09:00:00' })
    setShowAddRule(false)
  }

  const updateScheduleRule = (id, updates) => {
    setScheduleRules(
      scheduleRules.map((rule) =>
        rule.id === id ? { ...rule, ...updates } : rule
      )
    )
  }

  const deleteScheduleRule = (id) => {
    setScheduleRules(scheduleRules.filter((rule) => rule.id !== id))
    setEditingRule(null)
