                />
                <button onClick={() => setEditingRule(null)}>Done</button>
              </div>
            ) : (
              <div>
                {rule.day} at {rule.time}
                <button onClick={() => setEditingRule(rule.id)}>Edit</button>
                <button onClick={() => deleteScheduleRule(rule.id)}>
                  Delete
                </button>
              </div>
