import React from 'react'

const PresenceIndicator = ({ status, size }) => {
  let colorInner
  let colorOuter
  let widthInner
  let widthOuter

  switch (status) {
    case 'available':
      colorInner = '#4CEA94'
      colorOuter = '#4CEA9420'
      break
    case 'unavailable':
      colorInner = '#EA4C4C'
      colorOuter = '#EA4C4C20'
      break
    case 'not_invited':
      colorInner = '#FFFFFF66'
      colorOuter = '#FFFFFF33'
      break
  }

  switch (size) {
    case 'sm':
      widthInner = 6
      widthOuter = 10
      break
    case 'lg':
      widthInner = 8
      widthOuter = 14
      break
  }

  return (
    <div
      style={{
        backgroundColor: colorOuter,
        width: `${widthOuter}px`,
        height: `${widthOuter}px`,
        borderRadius: '50%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        animation: 'pulse 2s ease-in-out infinite',
      }}
    >
      <div
        style={{
          backgroundColor: colorInner,
          width: `${widthInner}px`,
          height: `${widthInner}px`,
          borderRadius: '50%',
        }}
      />
    </div>
  )
}

