import { useState } from 'react'
import { useSearchParams } from 'react-router'
import { useAuthStore } from '@/store/auth'
import { useContactsStore } from '@/store/contacts'

export default function ContactScreen() {
  const [params] = useSearchParams()
  const phone = params.get('phone') || ''
  const name = params.get('name') || ''
  const { isAuthenticated } = useAuthStore()
  const { addManualContact } = useContactsStore()
  const [added, setAdded] = useState(false)
  const [adding, setAdding] = useState(false)

  const appDeepLink = `zing://contact?phone=${encodeURIComponent(phone)}&name=${encodeURIComponent(name)}`

  const openInApp = () => {
    window.location.href = appDeepLink
  }

  const handleAddContact = async () => {
    if (!phone || adding) return
    setAdding(true)
    try {
      await addManualContact(name || phone, phone)
      setAdded(true)
    } catch (e) {
      console.error('Failed to add contact:', e)
    } finally {
      setAdding(false)
    }
  }

  if (!phone) {
    return (
      <div style={{ maxWidth: '400px', margin: '0 auto', padding: '20px 10px' }}>
        <p style={{ opacity: 0.6 }}>Invalid invite link.</p>
      </div>
    )
  }

  return (
    <div style={{ maxWidth: '400px', margin: '0 auto', padding: '20px 10px', textAlign: 'center' }}>
      <h1 style={{ margin: '0 0 8px 0' }}>BuzzBuzzMe</h1>

      <div
        style={{
          border: '1px solid #ccc',
          borderRadius: 12,
          padding: 20,
          margin: '16px 0',
        }}
      >
        <div
          style={{
            width: 64,
            height: 64,
            borderRadius: '50%',
            background: '#eee',
            margin: '0 auto 12px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 24,
          }}
        >
          {(name || phone).slice(0, 1).toUpperCase()}
        </div>
        <div style={{ fontWeight: 'bold', fontSize: 18 }}>{name || phone}</div>
        {name && <div style={{ opacity: 0.6, marginTop: 4 }}>{phone}</div>}
      </div>

      <button onClick={openInApp} style={{ width: '100%', marginBottom: 10 }}>
        Open in app
      </button>

      {isAuthenticated() ? (
        added ? (
          <p style={{ opacity: 0.7 }}>Added to your contacts!</p>
        ) : (
          <button onClick={handleAddContact} disabled={adding} style={{ width: '100%' }}>
            {adding ? 'Adding...' : 'Add to my contacts'}
          </button>
        )
      ) : (
        <a href="/login" style={{ display: 'inline-block', marginTop: 4, opacity: 0.7 }}>
          Log in to add this contact
        </a>
      )}

      <div style={{ marginTop: 24, fontSize: 13, opacity: 0.5 }}>
        <p style={{ margin: '4px 0' }}>Don't have the app yet?</p>
        <p style={{ margin: '4px 0' }}>
          <a href="https://apps.apple.com/app/yourappid">App Store</a>
          {' • '}
          <a href="https://play.google.com/store/apps/details?id=com.zingapp.app">Google Play</a>
        </p>
      </div>
    </div>
  )
}
